package sohal.lld.snakeladder.entity.factory;import sohal.lld.snakeladder.constants.Constants;import sohal.lld.snakeladder.entity.Entity;import sohal.lld.snakeladder.entity.Ladder;import sohal.lld.snakeladder.constants.Constants;import java.util.Set;import static sohal.lld.snakeladder.constants.Constants.*;public class LadderFactory implements EntityFactory {    public Entity createEntity(Set<Integer> usedPositions) {        int bottom, top;        while (true) {            bottom = RANDOM.nextInt(85) + 1;            int diff = RANDOM.nextInt(15) + 10;            top = bottom + diff;            if(top > SIZE) continue;            if(usedPositions.contains(top) || usedPositions.contains(bottom)) continue;            break;        }        usedPositions.add(top);        usedPositions.add(bottom);        return new Ladder(bottom, top);    }}